sfxOpen.addEventListener("durationchange", updateSummonAnimDuration);

/**
 * Plays a short sound effect. Clones the <audio> node so rapid repeats
 * (e.g. grabbing two coins back-to-back) overlap cleanly instead of the
 * new play() cutting off the previous one still ringing out.
 */
function playSfx(audioEl){
  if(isMuted) return;
  const node = audioEl.cloneNode(true);
  node.volume = SFX_VOLUME;
  node.play().catch(()=>{});
}

let isMuted = false;
function playLobbyMusic(){
  stageAudio.pause();
  halloweenAudio.pause();
  gardenAudio.pause();
  lobbyAudio.currentTime = lobbyAudio.currentTime || 0;
  lobbyAudio.play().catch(()=>{});
}
function playStageMusic(){
  lobbyAudio.pause();
  halloweenAudio.pause();
  gardenAudio.pause();
  stageAudio.currentTime = 0;
  stageAudio.play().catch(()=>{});
}
function playHalloweenMusic(){
  stageAudio.pause();
  lobbyAudio.pause();
  gardenAudio.pause();
  halloweenAudio.currentTime = 0;
  halloweenAudio.play().catch(()=>{});
}
