/* ---------- Heal potion tiers ----------
   A potion drops every 500 score. On a plain 500 mark (not a multiple of
   1000) the drop can roll ANY tier including the tiny one. On every 1000
   mark, the tiny tier is excluded so that milestone always guarantees at
   least a "small" heal or better.
   Bigger bottle = bigger heal, but bigger bottles are rarer
   (giant is the rarest, large is uncommon but a bit more common than giant). */
const POTION_TIERS_FULL = [
  { key:"tiny",   heal:10,  scale:0.55, weight:30, label:"จิ๋ว"  },
  { key:"small",  heal:25,  scale:0.75, weight:28, label:"เล็ก"  },
  { key:"medium", heal:50,  scale:1.0,  weight:24, label:"กลาง"  },
  { key:"large",  heal:75,  scale:1.35, weight:12, label:"ใหญ่"  },
  { key:"giant",  heal:100, scale:1.75, weight:6,  label:"ยักษ์" }
];
const POTION_TIERS_NO_TINY = [
  { key:"small",  heal:25,  scale:0.75, weight:35, label:"เล็ก"  },
  { key:"medium", heal:50,  scale:1.0,  weight:32, label:"กลาง"  },
  { key:"large",  heal:75,  scale:1.35, weight:20, label:"ใหญ่"  },
  { key:"giant",  heal:100, scale:1.75, weight:13, label:"ยักษ์" }
];
function pickPotionTier(pool){
  const total = pool.reduce((s,t)=>s+t.weight, 0);
  let r = Math.random() * total;
  for(const t of pool){
    if(r < t.weight) return t;
    r -= t.weight;
  }
  return pool[0];
}

