function isOwned(key){
  return key === "slime" || saveData.ownedCharacters.includes(key);
}

/**
 * Formats a coin amount for display: under 1,000 shows the exact number,
 * 1,000+ shows as "k" (e.g. 1000 -> "1k", 12500 -> "12.5k"), 1,000,000+
 * shows as "M" (e.g. 9000000 -> "9M"), 1,000,000,000+ shows as "B".
 * Keeps at most 1 decimal place and drops it when it's a whole number.
 */
function formatCoins(n){
  n = Math.floor(n);
  const abs = Math.abs(n);
  const UNITS = [
    { value: 1e9, suffix: "B" },
    { value: 1e6, suffix: "M" },
    { value: 1e3, suffix: "k" }
  ];
  for(const u of UNITS){
    if(abs >= u.value){
      let str = (n / u.value).toFixed(1);
      if(str.endsWith(".0")) str = str.slice(0, -2);
      return str + u.suffix;
    }
  }
  return String(n);
}

/* ============================================================
   PERSISTENT DATA (auto-save)
   ============================================================ */
const SAVE_KEY_PREFIX = "slimeRunnerSave_v1_"; // per-account save, keyed by username
const ACCOUNTS_KEY = "slimeRunnerAccounts_v1";
window.currentUser = null;

function loadAccounts(){
  try{
    const raw = localStorage.getItem(ACCOUNTS_KEY);
    if(raw) return JSON.parse(raw);
  }catch(e){}
  return {};
}
function saveAccounts(accounts){
  try{ localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts)); }catch(e){}
}

function loadSave(username){
  try{
    const raw = localStorage.getItem(SAVE_KEY_PREFIX + username);
    if(raw){
      const parsed = JSON.parse(raw);
      if(!parsed.ownedCharacters) parsed.ownedCharacters = ["slime"];
      if(!parsed.ownedCharacters.includes("slime")) parsed.ownedCharacters.push("slime");
      if(!parsed.equippedCharacter) parsed.equippedCharacter = "slime";
      if(typeof parsed.bestScore !== "number") parsed.bestScore = 0;
      if(!Array.isArray(parsed.ownedTreasures)) parsed.ownedTreasures = [];
      if(!Array.isArray(parsed.equippedTreasures)) parsed.equippedTreasures = [];
      delete parsed.leaderboard; // legacy multi-entry leaderboard no longer used
      return parsed;
    }
  }catch(e){}
  return { totalCoins:0, bestScore:0, ownedCharacters:["slime"], equippedCharacter:"slime", ownedTreasures:[], equippedTreasures:[] };
}
function saveSave(data){
  if(!currentUser) return;
  try{ localStorage.setItem(SAVE_KEY_PREFIX + currentUser, JSON.stringify(data)); }catch(e){}
}
// Placeholder until login/register succeeds and swaps this out via loadSave(username).
window.saveData = { totalCoins:0, bestScore:0, ownedCharacters:["slime"], equippedCharacter:"slime", ownedTreasures:[], equippedTreasures:[] };

/* ============================================================
   AUTH (LOGIN / REGISTER) — simple localStorage-based accounts.
   The auth overlay is visible by default (see #authLayer in the
   HTML) so it blocks the lobby until the player logs in.
   ============================================================ */
const authLayer = document.getElementById("authLayer");
const authLoginPanel = document.getElementById("authLoginPanel");
const authRegisterPanel = document.getElementById("authRegisterPanel");
const loginUsernameInput = document.getElementById("loginUsername");
const loginPasswordInput = document.getElementById("loginPassword");
const loginErrorEl = document.getElementById("loginError");
const regUsernameInput = document.getElementById("regUsername");
const regPasswordInput = document.getElementById("regPassword");
const regErrorEl = document.getElementById("regError");

function showAuthScreen(which){
  loginErrorEl.textContent = "";
  regErrorEl.textContent = "";
  if(which === "register"){
    authLoginPanel.classList.add("hidden");
    authRegisterPanel.classList.remove("hidden");
    regUsernameInput.focus();
  } else {
    authRegisterPanel.classList.add("hidden");
    authLoginPanel.classList.remove("hidden");
    loginUsernameInput.focus();
  }
}

async function loginSuccess(username){
  currentUser = username;
  await pullServerState(); // ดึงเหรียญ/คะแนน/ตัวละคร/สมบัติจริงจาก Supabase (กันโกง)
  loginUsernameInput.value = "";
  loginPasswordInput.value = "";
  regUsernameInput.value = "";
  regPasswordInput.value = "";
  loginErrorEl.textContent = "";
  regErrorEl.textContent = "";
  authLayer.classList.add("hidden");
  document.getElementById("lobbyUI").classList.remove("hidden");
  goToLobby();
}

async function handleLogin(){
  const u = loginUsernameInput.value.trim();
  const p = loginPasswordInput.value;
  loginErrorEl.textContent = "";
  if(!u || !p){ loginErrorEl.textContent = "กรุณากรอกชื่อผู้ใช้และรหัสผ่าน"; return; }

  const loginBtn = document.getElementById("loginConfirmBtn");
  loginBtn.disabled = true;
  let signInResult;
  try{
    signInResult = await sb.auth.signInWithPassword({
      email: usernameToFakeEmail(u),
      password: p
    });
  }catch(ex){
    loginBtn.disabled = false;
    alert("DEBUG signIn exception: " + (ex && ex.message ? ex.message : String(ex)));
    return;
  }
  const { error } = signInResult;
  loginBtn.disabled = false;

  if(error){
    alert("DEBUG signIn error: " + error.message + " (status: " + (error.status || "?") + ")");
    loginErrorEl.textContent = "ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง";
    return;
  }
  try{
    await loginSuccess(u);
  }catch(ex){
    alert("DEBUG loginSuccess exception: " + (ex && ex.message ? ex.message : String(ex)));
  }
}

async function handleRegister(){
  const u = regUsernameInput.value.trim();
  const p = regPasswordInput.value;
  regErrorEl.textContent = "";
  if(!u || !p){ regErrorEl.textContent = "กรุณากรอกชื่อผู้ใช้และรหัสผ่าน"; return; }
  if(!/^[a-zA-Z0-9_]{3,20}$/.test(u)){
    regErrorEl.textContent = "ชื่อผู้ใช้ต้องเป็นตัวอักษร/ตัวเลข/_ ยาว 3-20 ตัว";
    return;
  }
  if(p.length < 6){
    regErrorEl.textContent = "รหัสผ่านต้องยาวอย่างน้อย 6 ตัวอักษร";
    return;
  }

  const regBtn = document.getElementById("regConfirmBtn");
  regBtn.disabled = true;
  let signUpResult;
  try{
    signUpResult = await sb.auth.signUp({
      email: usernameToFakeEmail(u),
      password: p,
      options: { data: { username: u } }
    });
  }catch(ex){
    regBtn.disabled = false;
    alert("DEBUG signUp exception: " + (ex && ex.message ? ex.message : String(ex)));
    return;
  }
  const { error, data } = signUpResult;
  regBtn.disabled = false;

  if(error){
    alert("DEBUG signUp error: " + error.message + " (status: " + (error.status || "?") + ")");
    if(error.message && error.message.toLowerCase().includes("already")){
      regErrorEl.textContent = "ชื่อผู้ใช้นี้ถูกใช้แล้ว กรุณาใช้ชื่ออื่น";
    } else {
      regErrorEl.textContent = "สมัครสมาชิกไม่สำเร็จ: " + error.message;
    }
    return;
  }
  if(!data.session){
    alert("DEBUG: signUp สำเร็จแต่ไม่ได้ session กลับมา (อาจต้องยืนยันอีเมลอยู่ หรือ user มีอยู่แล้วแบบไม่ยืนยัน) data.user=" + JSON.stringify(data.user && data.user.id));
    regErrorEl.textContent = "สมัครไม่สำเร็จ กรุณาลองชื่ออื่น หรือติดต่อผู้ดูแล";
    return;
  }
  try{
    await loginSuccess(u);
  }catch(ex){
    alert("DEBUG loginSuccess exception (after register): " + (ex && ex.message ? ex.message : String(ex)));
  }
}

document.getElementById("loginConfirmBtn").addEventListener("click", handleLogin);
document.getElementById("regConfirmBtn").addEventListener("click", handleRegister);

// เช็ค session ค้างไว้ (ผู้เล่นเคย login แล้วยังไม่ signOut) — auto-login โดยไม่ต้องกรอกใหม่
(async function checkExistingSession(){
  const { data: { session } } = await sb.auth.getSession();
  if(session && session.user){
    const username = session.user.user_metadata && session.user.user_metadata.username;
    if(username){
      await loginSuccess(username);
    }
  }
})();
document.getElementById("goRegisterBtn").addEventListener("click", ()=>showAuthScreen("register"));
document.getElementById("backToLoginBtn").addEventListener("click", ()=>showAuthScreen("login"));
loginUsernameInput.addEventListener("keydown", e=>{ if(e.code === "Enter") loginPasswordInput.focus(); });
loginPasswordInput.addEventListener("keydown", e=>{ if(e.code === "Enter") handleLogin(); });
regUsernameInput.addEventListener("keydown", e=>{ if(e.code === "Enter") regPasswordInput.focus(); });
regPasswordInput.addEventListener("keydown", e=>{ if(e.code === "Enter") handleRegister(); });

async function addRunResult(score, coinsThisRun){
  const isNewBest = score > saveData.bestScore;
  // อัพเดท UI ทันทีแบบ optimistic เพื่อไม่ให้เกมกระตุก
  saveData.totalCoins += coinsThisRun;
  if(isNewBest) saveData.bestScore = score;

  // ค่าจริงที่ "นับ" จะมาจาก server เท่านั้น — ส่งไปตรวจสอบ/บันทึกฝั่ง Supabase
  try{
    await sb.rpc("submit_score", { p_score: score, p_distance: Math.round(score) });
    await sb.rpc("add_currency", { p_coin_delta: coinsThisRun, p_gem_delta: 0, p_reason: "run_reward" });
    if(isNewBest){
      // save which character + treasures were equipped for this new best run,
      // so the leaderboard can show them next to the score
      await sb.rpc("submit_score_loadout", {
        p_character: saveData.equippedCharacter,
        p_treasures: saveData.equippedTreasures
      });
    }
    // sync ค่าจริงจาก server กลับมา กันเคส client คำนวณคลาดเคลื่อน
    await pullServerState();
  }catch(e){
    console.error("addRunResult sync failed", e);
  }
}

/* ============================================================
   STATE MACHINE
   ============================================================ */
