let score = 0;
let coinsThisRun = 0;
let runSpeed = 260;         // px/sec base scroll speed
let stumble = 0;            // seconds of slowed speed after a hit
let elapsed = 0;

/* ---------- Ghoul character abilities (run-scoped, reset in resetRun()) ---------- */
let kaguneCooldown = 0;      // seconds left before the kagune shield (skill 1) can block again; 0 = ready
const KAGUNE_COOLDOWN_TIME = 10;
let awakeningActive = false; // true while skill 2 (Awakening) is currently in effect
let awakeningUsed = false;   // skill 2 can only trigger once per run
let awakeningTimer = 0;      // seconds left in the current Awakening window
const AWAKENING_DURATION = 10;
const AWAKENING_HEALTH_THRESHOLD = 30; // triggers automatically once health drops below this

/* ---------- Devil character abilities (run-scoped, reset in resetRun()) ---------- */
let devilEatCooldown = 0;    // seconds left before "ผู้กลืนกิน" can eat/block again; 0 = ready
const DEVIL_EAT_COOLDOWN_TIME = 15;
let devilReviveUsed = false; // "กำเนิดจอมมาร" can only trigger once per run

/* สมบัติ: กางเขนศักดิ์สิทธิ์ (cross) — revive-on-death skill state */
let crossReviveUsed = false;       // "พรแห่งการคืนชีพ" can only trigger once per run
let crossPostReviveShield = false; // guarantees the very next hazard hit after reviving is blocked

/* ---------- Hero character form-cycle state (run-scoped, reset in resetRun()) ---------- */
const HERO_CYCLE_TIME = 40;       // seconds spent in human form before transforming
const HERO_FORM_DURATION = 30;    // seconds spent in hero form
const HERO_TRANSFORM_DURATION = 5;// seconds each transform animation plays (both directions)
const HERO_SHIELD_COOLDOWN_TIME = 15; // seconds between hero-form damage blocks

// สมบัติประจำตัว: หูฟังฮีโร่ — only affects the "hero" character; equipping it
// on any other character does nothing (nothing reads these unless
// equippedCharacter === "hero" in the first place).
function heroCycleTime(){
  return isTreasureEquipped("headphone") ? 20 : HERO_CYCLE_TIME;
}
function heroFormDuration(){
  return isTreasureEquipped("headphone") ? 50 : HERO_FORM_DURATION;
}
function heroShieldCooldownTime(){
  return isTreasureEquipped("headphone") ? 10 : HERO_SHIELD_COOLDOWN_TIME;
}
let heroPhase = "human";          // "human" | "transformIn" | "hero" | "transformOut"
let heroCycleTimer = 0;           // counts up while in "human" phase
let heroFormTimer = 0;            // counts down while in "hero" phase
let heroTransformTimer = 0;       // counts up during either transform phase
let heroShieldCooldown = 0;       // only relevant/ticks while in "hero" phase

/* ---------- Obstacles & Coins (gameplay only) ---------- */
let rocks = [];   // {x, w, h}
let coins = [];   // {x, y, w, h, collected}
let potions = []; // {worldX, tier, size, collected, bob}
let popups = [];  // floating "+xx% HP" text feedback
let nextRockAt = 0;
let nextCoinAt = 0;
let nextPotionScore = 500; // spawn one heal potion every 500 score
