let stageTransitionAlpha = 0;  // 0 = fully stage1, 1 = fully stage2
let stageTransitioning = false;
let stage3TransitionAlpha = 0; // 0 = fully stage2, 1 = fully stage3
let stage3Transitioning = false;

/* Bats (stage 2 only) */
let bats = []; // same structure as birds but faster
